export const DEFAULT_KING_EMBLEM: KingEmblemId = "crown-triquetra";
export const KING_EMBLEM_KEY = "brandubh.kingEmblem";

const IDS = new Set<string>(KING_EMBLEMS.map((e) => e.id));
export function isKingEmblemId(v: unknown): v is KingEmblemId {
  return typeof v === "string" && IDS.has(v);
}
export function kingEmblemById(id: KingEmblemId): KingEmblemDef {
  return KING_EMBLEMS.find((e) => e.id === id) ?? KING_EMBLEMS[0];
}
/** King emblems available under the given rules (hides sword designs when the king is unarmed). */
export function availableKingEmblems(armedKing: boolean): KingEmblemDef[] {
  return KING_EMBLEMS.filter((e) => armedKing || !e.requiresArmedKing);
}
export function loadKingEmblem(): KingEmblemId {
  try {
    const s = localStorage.getItem(KING_EMBLEM_KEY);
    if (isKingEmblemId(s)) return s;
  } catch {
    /* ignore */
  }
  return DEFAULT_KING_EMBLEM;
}
